BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5a3b20b2409dbdd33b6e5de146408af9c01bd45c/content/books/zizhi-tongjian/vol-292/year-0956/part-01/sources/library/jiuwudaishi-116-january-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002746；EPUB电子本，纸本及异文待核", "id": "99d896fc-1490-5cb9-8e99-a9d1b356c4b8"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/tongjian-292-955-winter-huainan/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003471；电子底本待考，分段待核", "id": "a28d36a7-a0cd-5f98-9f39-3d49f1cd6b02"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/jiuwudaishi-115-december-955/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002743；EPUB电子本，纸本及异文待核", "id": "c819fc83-dec5-585e-8874-8eb00977a010"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/xinwudaishi-62-huainan-war-start/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003150；EPUB电子本，纸本及异文待核", "id": "41ca34ba-1f93-5a7e-97d9-e80c63f3a835"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "王环（后蜀凤州节度使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇州真定人，早年以勇力为孟知祥御者，后掌后蜀宿卫。开运末秦凤等地入蜀后，孟昶任其为凤州节度使。955年十一月凤州陷落时被后周军俘获。与914—929年楚水军将领王环分别保存，无同人证据。生卒年未载。", "biography": null, "status": "draft", "id": "abfc7768-1b27-5f09-bc3e-db6360a31dd2"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "王朴", "aliases": ["王樸"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "东平人，原任校书郎。951年任柴荣镇宁军掌书记。《旧五代史》记他字文伯，在后汉乾祐年间中进士，后来进入澶州幕府。生卒年尚未录入。", "biography": null, "status": "draft", "id": "aef64c13-19ef-556c-96f1-dd9e8fb91844"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "刘彦贞", "aliases": ["劉彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘信之子，南唐楚州刺史。944年条下追述他改任濠州观察使，迅速前往替代刘崇俊。具体任职年月与生卒年未载。", "biography": null, "status": "draft", "id": "3a86e5c0-cc8e-5120-888d-a75e599e8e30"}, {"name": "魏岑", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐齐王府僚属。李昪在位时，常梦锡曾反对他与陈觉、冯延巳等陪侍李璟。生卒年尚未核。", "biography": null, "status": "draft", "id": "58f25557-fd68-5851-90ad-b847734e7dfe"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "咸师朗", "aliases": ["咸師朗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蒙城镇将。949年南唐派皇甫晖到海州、泗州招纳淮北势力时，向皇甫晖投降。生卒年与其他经历未载。", "biography": null, "status": "draft", "id": "dc4e6f3f-cdad-5934-82a9-e901cc6f65dc"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "张全约", "aliases": ["張全約"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐池州刺史。956年正月与刘仁赡劝阻刘彦贞急追周军，未获听从。正阳战败后收拢余众退到寿州，刘仁赡上表任其为马步左厢都指挥使。生卒年未载。", "biography": null, "status": "draft", "id": "04f17d98-2900-5e03-8c82-d68f6db42489"}, {"name": "赵晁", "aliases": ["趙晁"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周控鹤都指挥使。954年三月向郑好谦表示宜慎重进军，郑转告柴荣后，两人被拘于怀州狱。生卒年未载。", "biography": null, "status": "draft", "id": "cd9622d4-b011-5634-b050-b6b748a36838"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：皇甫晖。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "姚凤", "aliases": ["姚鳳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年李璟任他为建州行营都监，与何敬洙、祖全恩率军增援查文徽。生卒年本段未载。", "biography": null, "status": "draft", "id": "74f180a4-a1e3-5952-a5d4-9d936d1a19ac"}, {"name": "王绍颜（南唐滁州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐滁州刺史。956年正阳之战后放弃城池逃走。是否与941年向李昪上书的同名内侍为同一人，尚无完整履历证据，暂分档保留。生卒年未载。", "biography": null, "status": "draft", "id": "a0cb9110-94be-5ba7-beb7-5e317dac3c4f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣任后蜀旧将王环为右骁卫大将军，奖励其此前守城不降", "start_year": 956, "end_year": 956, "time_original": "956年正月丙午", "dynasty": "五代十国", "description": "柴荣任后蜀旧将王环为右骁卫大将军，奖励其此前守城不降。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a8c413b3-49b3-56a9-baea-6956a4ef7815"}, {"title": "李谷奏报在上窑击败一千余南唐兵", "start_year": 956, "end_year": 956, "time_original": "956年正月丁酉奏报，交战日未单列", "dynasty": "五代十国", "description": "李谷奏报在上窑击败一千余南唐兵。", "phases": [], "location_name": "上窑", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "445892ce-bd1a-541f-b802-0c0e3ed4d3ee"}, {"title": "柴荣征发开封等地十余万民众修筑大梁外城", "start_year": 956, "end_year": 956, "time_original": "956年正月戊戌", "dynasty": "五代十国", "description": "柴荣征发开封等地十余万民众修筑大梁外城。", "phases": [], "location_name": "大梁外城，民夫来自开封府、曹州、滑州、郑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "adedf816-be8c-5a03-aea8-7448b512b539"}, {"title": "柴荣下诏亲征淮南", "start_year": 956, "end_year": 956, "time_original": "956年正月庚子", "dynasty": "五代十国", "description": "柴荣下诏亲征淮南。", "phases": [], "location_name": "后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "20f1a2ee-0d9b-575a-84fc-f4c91e18ef43"}, {"title": "柴荣安排向训、王朴留守东京，韩通掌京城侍卫巡检", "start_year": 956, "end_year": 956, "time_original": "《通鉴》接正月庚子诏令记部署；《旧五代史》向训王朴任命单列辛丑", "dynasty": "五代十国", "description": "柴荣亲征前，以宣徽南院使、镇安节度使向训暂任东京留守，端明殿学士王朴为副；彰信节度使韩通暂掌侍卫司和京城内外巡检。权表示暂任，未记三人永久离开原职。", "phases": [], "location_name": "东京大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "67fdb6a5-a1f5-507e-88bc-074875b0ebc9"}, {"title": "柴荣命李重进先赴正阳、白重赞率三千亲兵屯颍上", "start_year": 956, "end_year": 956, "time_original": "956年正月庚子诏令所附部署，具体到达日未载", "dynasty": "五代十国", "description": "柴荣命李重进先赴正阳、白重赞率三千亲兵屯颍上。", "phases": [], "location_name": "正阳、颍上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dce4aabe-5450-5d4e-b03d-1075d9bb1990"}, {"title": "柴荣离开大梁亲征", "start_year": 956, "end_year": 956, "time_original": "956年正月壬寅", "dynasty": "五代十国", "description": "柴荣离开大梁亲征。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b1ab1bd2-5643-53f6-933d-ff1ddade1b5a"}, {"title": "刘彦贞率兵赴来远镇，并以战舰威胁正阳浮桥", "start_year": 956, "end_year": 956, "time_original": "956年正月李谷退兵之前，具体日未载", "dynasty": "五代十国", "description": "李谷久攻寿州未克，刘彦贞率援军到来远镇，史书记其距寿州二百里；又派数百艘战舰趋正阳，形成威胁浮桥的态势。浮梁在此为浮桥，未记南唐已经把桥攻断。", "phases": [], "location_name": "寿州、来远镇、正阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c369cdca-9ba8-54c9-a736-b42953061040"}, {"title": "李谷因担心水战和浮桥被截，提议退守正阳待柴荣到来", "start_year": 956, "end_year": 956, "time_original": "956年正月寿州围攻期间，具体提议日未载", "dynasty": "五代十国", "description": "李谷因担心水战和浮桥被截，提议退守正阳待柴荣到来。", "phases": [], "location_name": "寿州军前", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "dcf8f809-c54d-57db-9b08-4bf2c585ab65"}, {"title": "柴荣在圉镇得知退兵计划，急派中使制止", "start_year": 956, "end_year": 956, "time_original": "956年正月壬寅离京以后、丁未到陈州以前", "dynasty": "五代十国", "description": "柴荣在圉镇得知退兵计划，急派中使制止。", "phases": [], "location_name": "圉镇至寿州军前", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2a42ea45-e04b-567c-a301-80cc39e999b6"}, {"title": "使者到达时，李谷已烧掉粮草并退守正阳", "start_year": 956, "end_year": 956, "time_original": "956年正月，具体退兵日未单列；《旧五代史》丁未奏报退守", "dynasty": "五代十国", "description": "使者到达时，李谷已烧掉粮草并退守正阳。", "phases": [], "location_name": "寿州至正阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1105efa7-2913-5543-b68a-7b3bd67c9846"}, {"title": "柴荣到陈州，急遣李重进进兵淮上", "start_year": 956, "end_year": 956, "time_original": "956年正月丁未", "dynasty": "五代十国", "description": "柴荣到陈州，急遣李重进进兵淮上。", "phases": [], "location_name": "陈州至淮上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b68faf4a-dee5-5c43-a720-460df324d5fa"}, {"title": "李谷奏请柴荣暂留陈颍，待解决水军和浮桥风险", "start_year": 956, "end_year": 956, "time_original": "956年正月辛亥奏报", "dynasty": "五代十国", "description": "李谷认为南唐战舰从河中推进、弩炮不能及，且淮水上涨，浮桥和粮道可能被截，因此请柴荣暂驻陈州、颍州，等李重进到后共商御舰保桥，并主张通过长期备战耗敌。柴荣看后不悦。这些风险和长期策略属于李谷的判断，不是粮道此时已被截断的事实。", "phases": [], "location_name": "正阳军前至柴荣行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7e7f4cd4-5c66-5d4e-85a6-39a3e44a4e06"}, {"title": "魏岑等称赞刘彦贞的治民和用兵能力", "start_year": null, "end_year": null, "time_original": "南征前旧事及任用背景，具体称赞年日未载", "dynasty": "五代十国", "description": "《通鉴》记魏岑等把刘彦贞的治民和用兵比作古代名臣名将，因此李璟在周军到来时首先任用他。这是他人赞辞与史家的任用解释，不是本站对刘彦贞能力的肯定。", "phases": [], "location_name": "南唐朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "68a80eec-8c13-5807-8459-28f636edb6d7"}, {"title": "刘彦贞、咸师朗等闻周军撤退后率军急追正阳", "start_year": 956, "end_year": 956, "time_original": "956年正月李谷退守之后、正阳之战之前", "dynasty": "五代十国", "description": "刘彦贞、咸师朗等闻周军撤退后率军急追正阳。", "phases": [], "location_name": "至正阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3521127e-382b-54be-8362-2c52ad3e1cd8"}, {"title": "刘仁赡、张全约劝阻刘彦贞急追，刘彦贞不听", "start_year": 956, "end_year": 956, "time_original": "956年正月正阳之战以前", "dynasty": "五代十国", "description": "刘仁赡和池州刺史张全约劝刘彦贞不要急追。刘仁赡说未交战而敌人先退，可能是畏其声威，急战一旦失利将危及大局。刘彦贞不听。这是劝告的理由，不证明周军撤退真的出于畏惧他。", "phases": [], "location_name": "南唐寿州援军", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2f9bfc1f-e853-50d4-ae6e-4165202fa667"}, {"title": "刘仁赡预言刘彦贞遇敌必败，加兵守寿州城", "start_year": 956, "end_year": 956, "time_original": "956年正月刘彦贞出发以后", "dynasty": "五代十国", "description": "刘仁赡预言刘彦贞遇敌必败，加兵守寿州城。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "92f918cb-8cf4-5554-b1fb-578204177f20"}, {"title": "李重进渡淮，在正阳东击败刘彦贞，杀死刘彦贞并俘咸师朗等", "start_year": 956, "end_year": 956, "time_original": "956年正月，《资治通鉴》本段未独立列战日；《旧五代史》辛亥奏报", "dynasty": "五代十国", "description": "李重进渡过淮河，在正阳东迎击南唐军并获胜。刘彦贞被杀，咸师朗等被俘。《通鉴》记斩首万余级、尸体延展三十里、收得军资器械三十余万；《旧五代史》奏报记斩首二万余级，戎甲三十万副、马五百匹。人数和物资统计口径分别保留，不相加为总数。", "phases": [], "location_name": "正阳东", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "81d086d9-c9a8-5d5e-ab43-0131188a4cb4"}, {"title": "《旧五代史》记赵晁杀害正阳战后三千余降兵", "start_year": 956, "end_year": 956, "time_original": "956年正月正阳之战后，具体日未载", "dynasty": "五代十国", "description": "《旧五代史》记赵晁杀害正阳战后三千余降兵。", "phases": [], "location_name": "正阳战后地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8d581e46-e860-55a3-b170-eaaa0b2b851b"}, {"title": "张全约收拢残兵退回寿州，刘仁赡上表任其为左厢都指挥使", "start_year": 956, "end_year": 956, "time_original": "956年正月正阳失利以后", "dynasty": "五代十国", "description": "《通鉴》记江淮长期安定、民众不惯战争，刘彦贞战败使南唐人恐惧。张全约收余众退到寿州，刘仁赡上表任他为马步左厢都指挥使。背景评价与退兵、任职分别说明，未写成已有全体民众测量结果。", "phases": [], "location_name": "寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c9065f59-bd4a-5e2e-84f6-f0402ebf352a"}, {"title": "皇甫晖、姚凤退守清流关", "start_year": 956, "end_year": 956, "time_original": "956年正月正阳之战后", "dynasty": "五代十国", "description": "皇甫晖、姚凤退守清流关。", "phases": [], "location_name": "清流关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e22055bb-fd0e-5e2c-b0bc-8e0d58535ccd"}, {"title": "滁州刺史王绍颜放弃城池逃走", "start_year": 956, "end_year": 956, "time_original": "956年正月正阳之战后", "dynasty": "五代十国", "description": "滁州刺史王绍颜放弃城池逃走。", "phases": [], "location_name": "滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "34621b2d-a251-5276-918a-8a22317da48f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

