SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣任后蜀旧将王环为右骁卫大将军，奖励其此前守城不降。", "citation": "卷292·显德三年（956年正月及相关追述）·zztj-v292-y0956-p001·原文件第74行", "note": "原文：春，正月，丙午，以王环为右骁卫大将军，赏其不降也。；核对说明：复用955年新建后蜀王环，不与楚水军王环合并；奖励不降指被俘前尽忠所事，不译成王环正在拒绝任命。", "status": "draft", "id": "ee5362ec-0aab-5c2d-a096-450d2c1067db", "subject_id": "a8c413b3-49b3-56a9-baea-6956a4ef7815", "source_id": "a28d36a7-a0cd-5f98-9f39-3d49f1cd6b02"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年正月丙午", "citation": "卷292·显德三年（956年正月及相关追述）·zztj-v292-y0956-p001·原文件第74行", "note": "原文：春，正月，丙午，以王环为右骁卫大将军，赏其不降也。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "7670c8ac-5db4-5e26-ac3f-072a300c102f", "subject_id": "a8c413b3-49b3-56a9-baea-6956a4ef7815", "source_id": "a28d36a7-a0cd-5f98-9f39-3d49f1cd6b02"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：任王环为右骁卫大将军。", "citation": "卷292·显德三年（956年正月及相关追述）·zztj-v292-y0956-p001·原文件第74行", "note": "原文：春，正月，丙午，以王环为右骁卫大将军，赏其不降也。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "317b1d8c-42be-597a-a2ac-aaadf4216039", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "a28d36a7-a0cd-5f98-9f39-3d49f1cd6b02"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：任王环为右骁卫大将军。", "citation": "卷292·显德三年（956年正月及相关追述）·zztj-v292-y0956-p001·原文件第74行", "note": "原文：春，正月，丙午，以王环为右骁卫大将军，赏其不降也。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "5f141892-1790-526f-8e4b-cc2f6ce3eff8", "subject_id": "f7d097d2-39cd-59e0-a345-d22eb18426bc", "source_id": "a28d36a7-a0cd-5f98-9f39-3d49f1cd6b02"}, {"subject_table": "person", "field_path": "description", "claim_text": "王环（后蜀凤州节度使）：因此前守凤州不降而获任。", "citation": "卷292·显德三年（956年正月及相关追述）·zztj-v292-y0956-p001·原文件第74行", "note": "原文：春，正月，丙午，以王环为右骁卫大将军，赏其不降也。；